export const TATSU_SKILLS={psychicbarrage:{cooldown:8,cast:.25,duration:1},gravitycrush:{cooldown:12,cast:.55,duration:1.1},repulsion:{cooldown:12,cast:.2,duration:.75},twistingstorm:{cooldown:16,cast:.65,duration:1.1}};
export const tatsumaki={name:'Tatsumaki',rangedBasic:true,assets:['tatsumaki','tatsumaki_vfx','tatsumaki_intro','tatsumaki_intro_vfx','tatsumaki_ultimate_vfx','tatsumaki_dialogue'],stats:{hp:1000,speed:205,melee:45,skillPower:100,cooldown:100,aggression:20,preferredRange:300,reactionChance:85},
 init(f){f.psychicZones=[];f.psychicSerial=0;f.rage=0;f.rageLockUntil=0;f.rageReadyTick=null;f.personalUses=0;f.psychicshotCd=.5*f.cooldownFactor;f.skillUses.psychicshot=0;for(const [k,v] of Object.entries({psychicbarrage:1,gravitycrush:3,repulsion:2,twistingstorm:5})){f[k+'Cd']=v*f.cooldownFactor;f.skillUses[k]=0;}},
 onAct(f,s,d){if(s==='psychicshot'){f.psychicshotCd=.9*f.cooldownFactor;f.skillUses.psychicshot++;}else if(TATSU_SKILLS[s]){f[s+'Cd']=TATSU_SKILLS[s].cooldown*f.cooldownFactor;f.skillUses[s]++;}else return;f.psychicHits=0;const t=d.pickTarget(f);f.psychicTarget=t?.uid;if(s==='gravitycrush'&&t){const z={uid:f.uid+':zone:'+ ++f.psychicSerial,kind:'crush',x:t.x,y:t.y,born:d.tick,detonate:d.tick+60,expires:d.tick+90};f.psychicZones.push(z);d.event('psychicMark',f,{x:z.x,y:z.y});}},
 tick(f,dt){for(const k of [...Object.keys(TATSU_SKILLS),'psychicshot'])f[k+'Cd']=Math.max(0,f[k+'Cd']-dt);},
 preferredApproachRange(f){return Math.max(180,f.preferredRange*.85);},
 danger(d,t){return d.fighters.some(f=>f.id==='tatsumaki'&&f.hp>0&&d.isEnemy(f,t)&&f.psychicZones.some(z=>z.kind==='crush'?!z.hit&&Math.hypot(t.x-z.x,t.y-z.y)<125:d.tick<z.expires&&Math.hypot(t.x-z.x,t.y-z.y)<100));},
 onDeath(d,f){f.psychicZones=[];},
 beforeStep(d,hits){for(const f of d.fighters){if(f.id!=='tatsumaki'||f.hp<=0)continue;for(const z of f.psychicZones){if(z.kind==='crush'&&!z.hit&&d.tick>=z.detonate){z.hit=true;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-z.x,t.y-z.y)<105)hits.push({source:f,target:t,value:180,knockback:25});d.event('psychicExplosion',f,{x:z.x,y:z.y,skill:'gravitycrush'});}
  if(z.kind==='storm'&&d.tick<z.expires){let target=d.fighters.find(t=>t.uid===z.targetUid&&t.hp>0&&d.isEnemy(f,t));if(!target){target=d.fighters.filter(t=>t.hp>0&&d.isEnemy(f,t)).reduce((best,t)=>!best||Math.hypot(t.x-z.x,t.y-z.y)<Math.hypot(best.x-z.x,best.y-z.y)?t:best,null);z.targetUid=target?.uid;}if(target){const dx=target.x-z.x,dy=target.y-z.y,distance=Math.hypot(dx,dy),speed=Math.min(150,distance*60);z.vx=distance?dx/distance*speed:0;z.vy=distance?dy/distance*speed:0;}z.x+=z.vx/60;z.y+=z.vy/60;d.clampPosition(z);if(d.tick>=z.nextHit){z.nextHit+=30;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-z.x,t.y-z.y)<85)hits.push({source:f,target:t,value:45});}}}f.psychicZones=f.psychicZones.filter(z=>d.tick<z.expires);}},
 updateAction(d,f,o,hits,dx,dy,dist,dt){const s=f.state,spec=TATSU_SKILLS[s]||(s==='psychicshot'?{cast:.2,duration:.5}:null);if(!spec)return false;const t=d.fighters.find(t=>t.uid===f.psychicTarget&&t.hp>0&&d.isEnemy(f,t))||o;
  const shoot=(kind,damage,angle=0)=>{const tx=t.x-f.x,ty=t.y-f.y,n=Math.hypot(tx,ty)||1,c=Math.cos(angle),sn=Math.sin(angle),ux=tx/n*c-ty/n*sn,uy=tx/n*sn+ty/n*c;f.face=Math.sign(tx)||f.face;d.shots.push({id:f.id,ownerUid:f.uid,kind,skill:kind,damage,damageKind:kind==='psychicbolt'?'melee':undefined,radius:kind==='psychicbolt'?16:22,x:f.x+ux*32,y:f.y+uy*32,vx:ux*560,vy:uy*560,life:1.25,impactEvent:'psychicImpact'});d.event('fire',f,{skill:kind});};
  if(s==='psychicbarrage'){while(f.psychicHits<3&&f.age>=[.25,.43,.61][f.psychicHits]){const i=f.psychicHits++;shoot('psychicrock',60,[-.06,0,.06][i]);}}
  else if(f.age>=spec.cast&&!f.hit){f.hit=true;if(s==='psychicshot')shoot('psychicbolt',f.melee);else if(s==='repulsion'){for(const target of d.fighters)if(target.hp>0&&d.isEnemy(f,target)&&Math.hypot(target.x-f.x,target.y-f.y)<150)hits.push({source:f,target,value:65,knockback:110});d.event('psychicRepulse',f,{x:f.x,y:f.y});}else if(s==='twistingstorm'){f.psychicZones.push({uid:f.uid+':zone:'+ ++f.psychicSerial,kind:'storm',x:f.x+f.actionX*80,y:f.y+f.actionY*80,vx:f.actionX*150,vy:f.actionY*150,targetUid:t?.uid,born:d.tick,nextHit:d.tick+15,expires:d.tick+240});d.event('psychicStorm',f,{x:f.x,y:f.y});}}
  if(s==='repulsion'&&f.age>=spec.cast&&f.age<.45&&d.tick>=(f.rootUntil||0)){f.x-=f.actionX*320*dt;f.y-=f.actionY*320*dt;d.clampPosition(f);}if(f.age>=spec.duration){f.state='idle';f.age=0;}return true;
 },
 chooseBasic(d,f,o,dx,dy,dist){if(f.psychicshotCd===0&&dist<650){d.act(f,'psychicshot',dx,dy);return true;}return false;},
 chooseSkill(d,f,o,dx,dy,dist){for(const k of ['repulsion','gravitycrush','twistingstorm','psychicbarrage'])if(f[k+'Cd']===0&&(k==='repulsion'?dist<155:k==='gravitycrush'?dist<650:k==='twistingstorm'?dist>160&&dist<560:dist<620)){d.act(f,k,dx,dy);return true;}return false;}
};
export function tatsumakiPose(f,hurt=false){if(f.introAge!=null){const a=f.introAge;if(a<.9)return {row:0,frame:Math.min(5,Math.floor(a/.9*6))};if(a<1.85)return {row:1,frame:Math.min(5,Math.floor((a-.9)/.95*6))};return {row:2,frame:Math.min(5,Math.floor((a-1.85)/.65*6))};}const s=hurt?'hurt':f.state,spec=TATSU_SKILLS[s]||(s==='psychicshot'?{duration:.5}:null);return {row:({idle:0,run:1,melee:2,psychicshot:2,beam:3,dash:1,guard:4,hurt:5,defeat:6,psychicbarrage:7,gravitycrush:8,repulsion:9,twistingstorm:10})[s]??0,frame:spec?Math.min(5,Math.floor(f.age/spec.duration*6)):['defeat','hurt','melee','dash','guard'].includes(s)?Math.min(5,Math.floor(f.age*10)):Math.floor(f.age*9)%6};}
